const data = $input.item.json;

// Extract the AI-generated response
let message = data.text ?? data.output ?? "";

// Ensure the response is a string
message = String(message).trim();

// Convert literal escaped newlines into actual newlines
message = message.replace(/\\n/g, "\n");

// Remove excessive blank lines
message = message.replace(/\n{3,}/g, "\n\n");

// Remove trailing whitespace from each line
message = message
    .split("\n")
    .map(line => line.trimEnd())
    .join("\n")
    .trim();

// Add a heading if the response doesn't already have one
if (!message.startsWith("🛒")) {
    message = `🛒 Recipe Ingredients\n\n${message}`;
}

return {
    json: {
        slackMessage: message,
        channel: $("Slack Trigger").item.json.channel
    }
};
